import itertools
import networkx as nx

def max_independent_set_size(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    G = nx.Graph()
    G.add_nodes_from(range(len(perms)))
    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            is_close = True
            for c in range(n):
                if abs(perms[i][c] - perms[j][c]) > 1:
                    is_close = False
                    break
            if is_close:
                G.add_edge(i, j)

    complement_G = nx.complement(G)
    # Using nx.approximation.maximum_independent_set or just max_clique.
    # Since it's small, max_clique should be fine.
    cliques = list(nx.find_cliques(complement_G))
    return max(len(c) for c in cliques)

for n in range(2, 6):
