def max_independent_set_size(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    G = nx.Graph()
    G.add_nodes_from(range(len(perms)))
    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            is_close = True
            for c in range(n):
                if abs(perms[i][c] - perms[j][c]) > 1:
                    is_close = False
                    break
            if is_close:
                G.add_edge(i, j)

    # We want the maximum independent set of G.
    # This is the maximum clique of the complement graph.
    # But we can also use the fact that for small graphs, we can find the max independent set.
    # Let's use a simpler method for max independent set.

    # Actually, nx.maximal_independent_set is just an approximation.
    # We can use the Bron-Kerbosch algorithm for max clique.
    # Or we can just use a simpler brute force if n is small.
    # Let's use the Bron-Kerbosch algorithm via nx.find_cliques.

    complement_G = nx.complement(G)
    max_size = 0
    for clique in nx.find_cliques(complement_G):
        if len(clique) > max_size:
            max_size = len(clique)
    return max_size

