import itertools

def max_indep_set(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    m = len(perms)
    adj = [0] * m
    for i in range(m):
        for j in range(m):
            if i != j and all(abs(perms[i][c] - perms[j][c]) <= 1 for c in range(n)):
                adj[i] |= (1 << j)

    memo = {}

    def backtrack(idx, mask):
        if idx == m:
            return 0
        if (idx, mask) in memo:
            return memo[(idx, mask)]

        # Option 1: Exclude idx
        res = backtrack(idx + 1, mask)

        # Option 2: Include idx if possible
        if not (mask & (1 << idx)):
            res = max(res, 1 + backtrack(idx + 1, mask | adj[idx] | (1 << idx)))

        memo[(idx, mask)] = res
        return res

    # Wait, the mask can be large, so memoization might not be effective.
    # But the mask only needs to contain bits from idx+1 to m-1.

    def backtrack_v2(idx, mask):
        if idx == m:
            return 0

        # mask only contains bits for indices >= idx
        mask &= ~((1 << idx) - 1)

        if (idx, mask) in memo:
            return memo[(idx, mask)]

        # Option 1: Exclude idx
        res = backtrack_v2(idx + 1, mask)

        # Option 2: Include idx if possible
        if not (mask & (1 << idx)):
            res = max(res, 1 + backtrack_v2(idx + 1, mask | adj[idx]))

        memo[(idx, mask)] = res
        return res

    return backtrack_v2(0, 0)

