import itertools

def get_neighbors(p):
    n = len(p)
    neighbors = []
    # A permutation q is a neighbor of p if |p(c)-q(c)| <= 1 for all c.
    # This means q is obtained by swapping disjoint pairs of adjacent values.
    # But it's easier to just iterate through all permutations for small n.
    for q in itertools.permutations(range(1, n + 1)):
        if p == q:
            continue
        if all(abs(p[i] - q[i]) <= 1 for i in range(n)):
            neighbors.append(q)
    return neighbors

def max_independent_set(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    m = len(perms)
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if all(abs(perms[i][c] - perms[j][c]) <= 1 for c in range(n)):
                adj[i].append(j)
                adj[j].append(i)

    # Max independent set using simple backtracking with pruning
    max_size = 0
    def backtrack(candidates, current_set):
        nonlocal max_size
        if not candidates:
            if len(current_set) > max_size:
                max_size = len(current_set)
            return
        if len(current_set) + len(candidates) <= max_size:
            return

        # Degree-based pruning
        v = candidates[0]
        min_deg = len([u for u in adj[v] if u in candidates])
        for cand in candidates:
            deg = len([u for u in adj[cand] if u in candidates])
            if deg < min_deg:
                min_deg = deg
                v = cand

        # Option 1: Include v
        new_candidates_with_v = [u for u in candidates if u != v and u not in adj[v]]
        backtrack(new_candidates_with_v, current_set + [v])

        # Option 2: Exclude v
        new_candidates_without_v = [u for u in candidates if u != v]
        backtrack(new_candidates_without_v, current_set)

    backtrack(list(range(m)), [])
    return max_size

